package com.shabakaty.cinemana.local;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.DocumentsContract;import android.graphics.*;import android.view.*;import android.widget.*;
import java.io.*;import java.text.SimpleDateFormat;import java.util.*;
import com.shabakaty.cinemana.local.LocalAccountStore.*;

/** Account editor and SAF backup UI. Reads, image decoding and ZIP work run on the serial worker. */
public final class LocalAccountActivity extends Activity {
 private LinearLayout content;private EditText name;private ImageView avatar;private byte[] selected;private boolean busy;private boolean restartAfterImport;private String draftName;private int background,raised,primary,muted;private String operation="account";
 public void onCreate(Bundle state){super.onCreate(state);LocalRuntime.init(this);render();LocalRuntime.IO.execute(()->{try{LocalRuntime.refreshStorage();runOnUiThread(()->{if(!isFinishing()){if(name!=null&&name.hasFocus())draftName=name.getText().toString();render();}});}catch(Exception e){LocalRuntime.failure("storage_open",e);}});if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},266);}
 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private int color(String attr,int fallback){int id=getResources().getIdentifier(attr,"attr",getPackageName());android.util.TypedValue value=new android.util.TypedValue();return id!=0&&getTheme().resolveAttribute(id,value,true)&&value.type>=16&&value.type<=31?value.data:fallback;}
 private android.graphics.drawable.GradientDrawable rounded(int fill,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));return d;}
 private void render(){
  background=color("cinColorBackground",0xff101214);raised=color("cinColorSurfaceRaised",0xff20272d);primary=color("cinColorTextPrimary",0xfff4f5f7);muted=color("cinColorTextSecondary",0xffaab0b5);
  ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(background);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(12),dp(20),dp(28));content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);content.setFocusableInTouchMode(true);scroll.addView(content);setContentView(scroll);setTitle("تعديل");
  if(Build.VERSION.SDK_INT>=21){getWindow().setStatusBarColor(background);getWindow().setNavigationBarColor(background);}
  LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);content.addView(toolbar,new LinearLayout.LayoutParams(-1,dp(52)));
  TextView back=new TextView(this);back.setText("→");back.setTextColor(primary);back.setTextSize(30);back.setGravity(Gravity.CENTER);back.setContentDescription("رجوع");toolbar.addView(back,new LinearLayout.LayoutParams(dp(48),-1));back.setOnClickListener(v->finish());
  TextView title=new TextView(this);title.setText("تعديل");title.setTextSize(22);title.setTextColor(primary);toolbar.addView(title);
  LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(0,dp(24),0,dp(24));content.addView(header,new LinearLayout.LayoutParams(-1,-2));
  avatar=new ImageView(this);avatar.setScaleType(ImageView.ScaleType.CENTER_CROP);avatar.setBackground(rounded(raised,64));avatar.setClipToOutline(true);avatar.setContentDescription("صورة الحساب");header.addView(avatar,new LinearLayout.LayoutParams(dp(112),dp(112)));
  LinearLayout summary=new LinearLayout(this);summary.setOrientation(1);summary.setPadding(dp(20),0,dp(20),0);header.addView(summary,new LinearLayout.LayoutParams(0,-2,1));
  TextView display=new TextView(this);display.setText(draftName==null?LocalRuntime.name():draftName);display.setTextColor(primary);display.setTextSize(22);display.setTypeface(null,1);summary.addView(display);
  Button picture=new Button(this);picture.setText("تغيير الصورة");picture.setAllCaps(false);picture.setTextColor(primary);picture.setBackground(rounded(raised,12));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(46));pp.topMargin=dp(12);summary.addView(picture,pp);picture.setOnClickListener(v->{if(!busy){draftName=name.getText().toString();pickImage();}});
  text("الملف الشخصي",19);text("الاسم",14);
  name=new EditText(this);name.setSingleLine(true);name.setTextColor(primary);name.setTextSize(17);name.setHintTextColor(muted);name.setHint("اسم المستخدم");name.setText(draftName==null?LocalRuntime.name():draftName);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(80)});name.setBackground(rounded(raised,12));name.setPadding(dp(16),0,dp(16),0);content.addView(name,new LinearLayout.LayoutParams(-1,dp(54)));
  button("حفظ التغييرات",()->{final String value=name.getText().toString().trim();if(value.isEmpty()){toast("اكتب الاسم أولاً");return;}draftName=value;operation="profile_save";work(()->{LocalAccountStore store=LocalRuntime.data();store.profile(value,selected==null?store.avatar():selected);LocalRuntime.updateProfile();selected=null;},"تم حفظ التغييرات");},true);
  View divider=new View(this);divider.setBackgroundColor(raised);LinearLayout.LayoutParams line=new LinearLayout.LayoutParams(-1,dp(1));line.topMargin=dp(28);line.bottomMargin=dp(16);content.addView(divider,line);
  text("النسخ الاحتياطي",19);
  button("تصدير نسخة احتياطية",()->{draftName=name.getText().toString();operation="backup_export";LocalRuntime.log("backup_folder_picker");Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);startActivityForResult(intent,2);},false);
  button("استيراد نسخة احتياطية",()->{operation="backup_import";draftName=name.getText().toString();new AccountUi.Builder(this).setTitle("استيراد نسخة احتياطية").setMessage("ستُستبدل بيانات الحساب الحالية ببيانات النسخة المختارة.").setNegativeButton("إلغاء",null).setPositiveButton("اختيار الملف",(d,w)->pick("application/zip",3)).show();},false);
  content.requestFocus();
  if(LocalRuntime.store!=null){text("مكان حفظ الحساب",14);TextView location=new TextView(this);location.setText(LocalRuntime.store.directory().getAbsolutePath());location.setTextSize(12);location.setTextColor(muted);location.setTextIsSelectable(true);content.addView(location);if(!LocalRuntime.store.directory().equals(LocalRuntime.sharedDirectory()))button("السماح بحفظ الحساب في مجلد سينمانا",()->{if(Build.VERSION.SDK_INT>=23)requestPermissions(new String[]{"android.permission.READ_EXTERNAL_STORAGE","android.permission.WRITE_EXTERNAL_STORAGE"},268);},false);}
  LocalRuntime.IO.execute(()->{try{final byte[] bytes=selected==null?LocalRuntime.data().avatar():selected;final Bitmap bitmap=bytes.length==0?null:BitmapFactory.decodeByteArray(bytes,0,bytes.length);runOnUiThread(()->{if(!isFinishing()){if(bitmap!=null)avatar.setImageBitmap(bitmap);else{int icon=getResources().getIdentifier("ic_profile","drawable",getPackageName());avatar.setImageResource(icon==0?android.R.drawable.ic_menu_myplaces:icon);}}});}catch(Exception e){LocalRuntime.failure("profile_load",e);}});
 }
 private void text(String label,int size){TextView view=new TextView(this);view.setText(label);view.setTextSize(size);view.setTextColor(size>=19?primary:muted);view.setPadding(0,dp(12),0,dp(10));content.addView(view);}
 private void button(String label,final Runnable action,boolean save){Button button=new Button(this);button.setText(label);button.setTextSize(16);button.setAllCaps(false);button.setTextColor(save?background:primary);button.setBackground(rounded(save?primary:raised,12));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(52));params.topMargin=dp(16);content.addView(button,params);button.setOnClickListener(v->{if(!busy)action.run();});}
 private void pickImage(){String[] labels=Build.VERSION.SDK_INT>=33?new String[]{"معرض الهاتف","منتقي الصور","الملفات"}:new String[]{"معرض الهاتف","الملفات"};new AccountUi.Builder(this).setTitle("اختيار صورة").setItems(labels,(dialog,index)->{
  try{operation="photo";if(index==0){Intent gallery=new Intent(Intent.ACTION_GET_CONTENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);Intent files=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);Intent chooser=Intent.createChooser(gallery,"اختيار صورة");chooser.putExtra(Intent.EXTRA_INITIAL_INTENTS,new Intent[]{files});startActivityForResult(chooser,1);}else if(Build.VERSION.SDK_INT>=33&&index==1)startActivityForResult(new Intent("android.provider.action.PICK_IMAGES").setType("image/*"),1);else pick("image/*",1);}catch(ActivityNotFoundException e){pick("image/*",1);}
 }).setNegativeButton("إلغاء",null).show();}
 private void saveZipFile(){operation="backup_export";String filename="Cinemana-account-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+".zip";Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(intent,4);}
 private void prepareBackup()throws Exception{LocalRuntime.log("backup_snapshot_begin");LocalRuntime.flushProgress();LocalRuntime.snapshotLegacy(!LocalRuntime.data().config("legacy_seeded","0").equals("1"));LocalRuntime.log("backup_snapshot_ready");}
 private void pick(String type,int code){if(busy)return;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(type).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,code);}
 private interface Task{void run()throws Exception;}
 private void work(final Task task,final String success){if(busy)return;busy=true;toast("جارٍ التنفيذ…");LocalRuntime.IO.execute(new Runnable(){public void run(){try{task.run();runOnUiThread(()->{busy=false;if(!isFinishing()){toast(success);if(restartAfterImport){Intent launch=getPackageManager().getLaunchIntentForPackage(getPackageName());if(launch!=null){launch.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(launch);finish();return;}}render();}});}catch(final Exception e){LocalRuntime.failure(operation,e);runOnUiThread(()->{busy=false;if(!isFinishing()){toast("تعذر إكمال العملية؛ راجع سجل التشخيص.");if(operation.equals("backup_export"))new AccountUi.Builder(LocalAccountActivity.this).setTitle("طريقة حفظ بديلة").setMessage("يمكن اختيار ملف ZIP مباشرة بدلاً من المجلد.").setPositiveButton("حفظ ملف ZIP",(d,w)->saveZipFile()).setNegativeButton("إغلاق",null).show();}});}}});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;LocalRuntime.log("account_picker_result code="+request);final Uri uri=data.getData();
  if(request==1)work(()->{byte[] bytes=read(uri,8*1024*1024);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);
   if(bounds.outWidth<=0||bounds.outHeight<=0||(long)bounds.outWidth*bounds.outHeight>100000000)throw new IOException("invalid image");
   BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=1;while(Math.max(bounds.outWidth,bounds.outHeight)/options.inSampleSize>512)options.inSampleSize*=2;
   Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap==null)throw new IOException("invalid image");ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.JPEG,85,out);bitmap.recycle();
   selected=out.toByteArray();},"تم اختيار الصورة؛ اضغط حفظ التغييرات");
  else if(request==2)work(()->{
   prepareBackup();
   LocalRuntime.log("backup_folder_selected");Uri parent=DocumentsContract.buildDocumentUriUsingTree(uri,DocumentsContract.getTreeDocumentId(uri));String filename="Cinemana-account-"+new SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+".zip";
   Uri target=DocumentsContract.createDocument(getContentResolver(),parent,"application/zip",filename);if(target==null)throw new IOException("document not created");
   try(OutputStream out=getContentResolver().openOutputStream(target,"w")){if(out==null)throw new IOException("document not writable");LocalRuntime.data().exportZip(out);}catch(Exception e){try{DocumentsContract.deleteDocument(getContentResolver(),target);}catch(Exception ignored){}throw e;}
  },"تم تصدير النسخة إلى المجلد المختار");
  else if(request==4)work(()->{prepareBackup();try(OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("document not writable");LocalRuntime.data().exportZip(out);}},"تم تصدير النسخة الاحتياطية");
  else if(request==3)work(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("document not readable");LocalRuntime.importAccount(in);}selected=null;draftName=null;LocalRuntime.updateProfile();LocalRuntime.restoreLegacy();LocalRuntime.log("ui_refresh_after_import");restartAfterImport=true;},"تم استيراد الحساب وتحديث البيانات");
 }
 public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==268)work(()->LocalRuntime.refreshStorage(),"تم تحديث مكان الحفظ");}
 private byte[] read(Uri uri,int limit)throws IOException{try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("image unreadable");byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("image limit");out.write(b,0,n);}return out.toByteArray();}}
 private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
}
